export class VVC {
    static getNalType(unit: any): number | undefined;
    static getNalTypes(units: any): any;
    static getNalInfo(units: any): {
        nalTypes: any;
        randomAccessType: string;
        rasl: any;
    } | undefined;
    /**
     * Per RFC 9328 the VVC codec string is:
     *   <SampleEntry4CC>.<general_profile_idc>.<L|H><general_level_idc>[.C<constraints>][.O<sub_profiles>]
     * where:
     *   - SampleEntry4CC: 'vvc1' or 'vvi1'
     *   - tier code 'L' for Main tier (general_tier_flag = 0), 'H' for High tier
     * We only emit the 4CC + profile + tier/level part here; constraint/sub-profile
     * info is optional and not required by MSE for isTypeSupported checks.
     */
    static buildCodecString(sampleEntryType: any, ptlRecord: any): string;
    /**
     * Parse a standard VVC decoder configuration record carried inside `vvcC`
     * next to `vvc1` / `vvi1` sample entries.
     */
    static parseVVCDecoderConfigurationRecord(data: any, sampleEntryType: any): {
        data: any;
        codec: string;
        sampleEntryType: any;
        nalUnitSize: number;
        ptlPresentFlag: number;
        olsIdx: number | undefined;
        numSublayers: number;
        constantFrameRate: number | undefined;
        chromaFormatIdc: number | undefined;
        bitDepthLumaMinus8: number | undefined;
        ptlRecord: {};
        width: any;
        height: any;
        sampleRate: any;
        numOfArrays: any;
        vps: any[];
        sps: any[];
        pps: any[];
        spsParsed: {
            width: number;
            height: number;
            spsMaxSubLayerMinus1: number;
            spsVideoParameterSetId: number;
            chromaFormatIdc: number;
            chromaFormat: number;
            ptlInfo: {
                generalProfileIdc: any;
                generalTierFlag: any;
                generalLevelIdc: any;
                ptlFrameOnlyConstraintFlag: any;
                ptlMultilayerEnabledFlag: any;
                ptlSublayerLevelPresentFlags: any[];
                ptlSublayerLevelIdcs: any[];
                ptlSubProfileIdcs: any[];
                gciInfo: {
                    gciPresentFlag: any;
                } | undefined;
            };
        } | null;
    };
    /**
     * Standard VvcDecoderConfigurationRecord per ISO/IEC 14496-15:2022 / Amd.2.
     */
    static _parseStandardVvcConfigurationRecord(data: any, sampleEntryType: any): {
        data: any;
        codec: string;
        sampleEntryType: any;
        nalUnitSize: number;
        ptlPresentFlag: number;
        olsIdx: number | undefined;
        numSublayers: number;
        constantFrameRate: number | undefined;
        chromaFormatIdc: number | undefined;
        bitDepthLumaMinus8: number | undefined;
        ptlRecord: {};
        width: any;
        height: any;
        sampleRate: any;
        numOfArrays: any;
        vps: any[];
        sps: any[];
        pps: any[];
        spsParsed: {
            width: number;
            height: number;
            spsMaxSubLayerMinus1: number;
            spsVideoParameterSetId: number;
            chromaFormatIdc: number;
            chromaFormat: number;
            ptlInfo: {
                generalProfileIdc: any;
                generalTierFlag: any;
                generalLevelIdc: any;
                ptlFrameOnlyConstraintFlag: any;
                ptlMultilayerEnabledFlag: any;
                ptlSublayerLevelPresentFlags: any[];
                ptlSublayerLevelIdcs: any[];
                ptlSubProfileIdcs: any[];
                gciInfo: {
                    gciPresentFlag: any;
                } | undefined;
            };
        } | null;
    };
    /**
     * Shared helper that walks the `num_of_arrays` loop at the tail of a VVC
     * decoder configuration record. DCI (13) and OPI (12) NAL types carry a
     * single NAL without a num_nalus count per Amd.2.
     */
    static _parseVVCNalArrays(reader: any): {
        numOfArrays: any;
        vps: any[];
        sps: any[];
        pps: any[];
        spsParsed: {
            width: number;
            height: number;
            spsMaxSubLayerMinus1: number;
            spsVideoParameterSetId: number;
            chromaFormatIdc: number;
            chromaFormat: number;
            ptlInfo: {
                generalProfileIdc: any;
                generalTierFlag: any;
                generalLevelIdc: any;
                ptlFrameOnlyConstraintFlag: any;
                ptlMultilayerEnabledFlag: any;
                ptlSublayerLevelPresentFlags: any[];
                ptlSublayerLevelIdcs: any[];
                ptlSubProfileIdcs: any[];
                gciInfo: {
                    gciPresentFlag: any;
                } | undefined;
            };
        } | null;
    };
    static parseVVCPTLRecord(reader: any, numSublayers: any): {
        generalProfileIdc: number;
        generalTierFlag: number;
        generalLevelIdc: any;
        ptlFrameOnlyConstraintFlag: number;
        ptlMultilayerEnabledFlag: number;
        generalConstraintInfo: Uint8Array<ArrayBuffer>;
        subLayerLevelIdc: any[];
        generalSubProfileIdc: any[];
        ptlNumSubProfiles: any;
        numBytesConstraintInfo: number;
    };
    static getAvccNals(buffer: any): {
        header: any;
        body: Uint8Array<any>;
    }[];
    static analyseNal(unit: any): void;
    static removeEPB(uint: any): any;
    static parseVps(): void;
    static parseSPS(sps: any): {
        width: number;
        height: number;
        spsMaxSubLayerMinus1: number;
        spsVideoParameterSetId: number;
        chromaFormatIdc: number;
        chromaFormat: number;
        ptlInfo: {
            generalProfileIdc: any;
            generalTierFlag: any;
            generalLevelIdc: any;
            ptlFrameOnlyConstraintFlag: any;
            ptlMultilayerEnabledFlag: any;
            ptlSublayerLevelPresentFlags: any[];
            ptlSublayerLevelIdcs: any[];
            ptlSubProfileIdcs: any[];
            gciInfo: {
                gciPresentFlag: any;
            } | undefined;
        };
    };
    static _parseProfileTierLevel(eg: any, ptPresentFlag: any, spsMaxSubLayerMinus1: any): {
        generalProfileIdc: any;
        generalTierFlag: any;
        generalLevelIdc: any;
        ptlFrameOnlyConstraintFlag: any;
        ptlMultilayerEnabledFlag: any;
        ptlSublayerLevelPresentFlags: any[];
        ptlSublayerLevelIdcs: any[];
        ptlSubProfileIdcs: any[];
        gciInfo: {
            gciPresentFlag: any;
        } | undefined;
    };
    static _parseGeneralConstraintsInfo(eg: any): {
        gciPresentFlag: any;
    };
}
